```text
NS_IMETHODIMP nsMsgProgress::GetMsgWindow(nsIMsgWindow** aMsgWindow) {
  NS_ENSURE_ARG_POINTER(aMsgWindow);

  if (m_msgWindow)
    CallQueryReferent(m_msgWindow.get(), aMsgWindow);
  else
    *aMsgWindow = nullptr;

  return NS_OK;
}
```

[xpcom/base/nsIWeakReferenceUtils.h:22-27](https://github.com/mozilla-firefox/firefox/blob/1a097ed8d31f6b307a5d0ebc34a82ceaf7f3727b/xpcom/base/nsIWeakReferenceUtils.h#L22-L27)

```text
inline nsresult CallQueryReferent(T* aSource, DestinationType** aDestination) {
  MOZ_ASSERT(aSource, "null parameter");
  MOZ_ASSERT(aDestination, "null parameter");

  return aSource->QueryReferent(NS_GET_IID(DestinationType),
                                reinterpret_cast<void**>(aDestination));
```

